import { FACTIONS, IDEOLOGIES, RESOURCES } from './data.js';
import { marketDemand } from './trade.js';
import { serviceCount } from './infrastructure.js';
import { policyEffects } from './governance.js';
import { esc,fmt } from './ui-format.js';
const btn=(label,id,kind,disabled=false)=>`<button class="button secondary" data-action="diplomacy" data-faction="${id}" data-kind="${kind}" ${disabled?'disabled':''}>${label}</button>`;
export function diplomacyPanel(state,ui) {
 const active=ui.diplomacyFaction??'ilyri';
 const advanced=state.tech.includes('advancedDiplomacy')&&state.planets.some(p=>p.owner==='player'&&serviceCount(p,'diplomacy'));
 return `<p class="lede">Die Reiche verfolgen eigene wirtschaftliche Ziele. Eingehaltene Lieferverträge schaffen Vertrauen. Wähle ein Reich, um seine Märkte, Interessen und Abkommen zu verwalten.</p>${Object.entries(state.relations).map(([id,r])=>{
 const planets=state.planets.filter(p=>p.owner===id&&!p.destroyed),exists=planets.length>0,pact=r.pactUntil>state.day,profile=policyEffects(state,id);
 const imports=planets.flatMap(p=>Object.keys(RESOURCES).map(k=>({p,k,need:Math.max(0,marketDemand(state,p,k)-(p.lastReport?.productionByResource?.[k]??0))}))).filter(q=>q.need>.1).sort((a,b)=>b.need-a.need).slice(0,3);
 return `<div class="detail-card faction-card"><button class="faction-focus" data-action="diplomacy-focus" data-faction="${id}"><strong style="color:${FACTIONS[id].color}">${FACTIONS[id].name}</strong><span class="status-badge">${!exists?'Keine Kolonien':r.war?'Krieg':r.embargo?'Sanktionen':r.cooperation?'Partner':r.trade?'Handel':'Frieden'}</span></button><p>${FACTIONS[id].species} · ${IDEOLOGIES[FACTIONS[id].ideology].name} · Beziehungen ${fmt(r.score)}</p><div ${active!==id?'hidden':''}><p><strong>Interesse:</strong> ${FACTIONS[id].goal}</p><p class="note">Regierungsprofil: Forschung ×${profile.science.toFixed(2)} · Arbeitskräfte ×${profile.workers.toFixed(2)} · Zufriedenheit ${profile.happiness>=0?'+':''}${profile.happiness}<br>Diese Werte gelten tatsächlich für die fremden Planeten. Eigene Forschung und Gesetze entwickeln sich im Spielverlauf weiter.</p><p class="note">${imports.length?`Regelmäßiger Importbedarf: ${imports.map(q=>`${RESOURCES[q.k].name} auf ${esc(q.p.name)} (${fmt(q.need)} / Tag)`).join(' · ')}`:'Die aktuellen Produktionsketten sind weitgehend eigenständig.'}</p><p class="note">Handel ab 0 · Nichtangriffspakt ab 35 · Partnerschaft ab 50</p>${r.trade?'<p>Handel offen: Frachter können Waren verkaufen und Rückfracht einkaufen.</p>':''}${r.cooperation?'<p>Partnerschaft: +8 % Forschung · +12 % Exporterlös.<br>Im Krieg alle 60 Tage: +12 Legierungen, +4 Waffen, +4 Verteidigung, sofern der Partner Vorräte hat.</p>':''}${pact?`<p>Nichtangriffspakt: noch ${r.pactUntil-state.day} Tage. Vor einer Kriegserklärung kündigen.</p>`:''}${r.embargo?'<p>Sanktionen: Produktion dieses Reichs −15 %; dein Haushalt −1,5 ¢ / Tag. Handel und Partnerschaft sind gesperrt.</p>':''}
 ${r.war?btn('Waffenstillstand · 120 ¢',id,'peace',state.credits<120):`${btn(r.envoyReady>state.day?`Gesandtschaft in ${r.envoyReady-state.day} Tagen`:'Gesandtschaft · 60 ¢',id,'envoy',state.credits<60||r.envoyReady>state.day)}${!r.trade?btn('Handelsabkommen · 50 ¢',id,'trade',!exists||r.embargo||r.score<0||state.credits<50):`<button class="button primary" data-action="trade-open" data-faction="${id}">Handelsroute einrichten</button>`}${btn(pact?'Pakt kündigen · −15 Beziehungen':'Nichtangriffspakt · 100 ¢',id,pact?'cancel-pact':'pact',!pact&&(!exists||r.embargo||r.score<35||state.credits<100))}${btn(r.cooperation?'Partnerschaft beenden':'Partnerschaft · 180 ¢',id,r.cooperation?'cancel-cooperation':'cooperation',!r.cooperation&&(!exists||!r.trade||r.embargo||r.score<50||state.credits<180))}`}
 <div class="section-title">Erweiterte Abkommen</div>${!advanced?'<p class="research-condition unmet">Benötigt: Interstellare Vertragsdiplomatie und aktives Diplomatisches Forum.</p>':''}${btn(r.portAccess?'Hafennutzung beenden':'Hafenabkommen · 80 ¢',id,r.portAccess?'cancel-ports':'ports',!r.portAccess&&(!advanced||!r.trade||r.score<15||state.credits<80))}<p class="note">Versorgung und Reparatur an fremden Häfen gegen Warenpreise und Servicekosten. Ausgaben erscheinen im laufenden Haushalt.</p>${btn(r.researchPact?'Forschungsaustausch beenden':'Forschungsaustausch · 160 ¢',id,r.researchPact?'cancel-research-pact':'research-pact',!r.researchPact&&(!advanced||!r.trade||r.score<35||state.credits<160))}<p class="note">Zusätzlich +6 % Laborertrag.</p>${btn(r.defensePact?'Beistandsabkommen beenden':'Beistandsabkommen · 120 ¢',id,r.defensePact?'cancel-defense-pact':'defense-pact',!r.defensePact&&(!advanced||!r.trade||r.score<50||state.credits<120))}<p class="note">2 ¢ Unterhalt / Tag. Bei eigenen Kriegen alle 30 Tage: +12 Legierungen, +4 Waffen und +12 Verteidigung, wenn der Partner Material besitzt.</p>
 ${btn(r.embargo?'Sanktionen aufheben':'Sanktionen · 1,5 ¢ / Tag',id,r.embargo?'lift-embargo':'embargo',!exists&&!r.embargo)}${!r.war?`<button class="button danger" data-action="war-confirm" data-faction="${id}" ${pact||!exists?'disabled':''}>${ui.warConfirm===id?'Kriegserklärung bestätigen':'Krieg erklären'}</button>`:''}</div></div>`;
 }).join('')}`;
}
